package assign

import (
	"encoding/json"
	"os"
	"reflect"
	"testing"

	"github.com/johnendean/herdrcolor/internal/palette"
)

// testdata/parity.json was generated by the Python implementation (commit
// 8851a5d) before it was removed. It is the proof that the port gives every
// project the colour it already had, so it must never be regenerated from the
// Go code.
type parity struct {
	Hashes map[string]int `json:"hashes"`
	Cases  []struct {
		Agents     []Agent     `json:"agents"`
		Workspaces []Workspace `json:"workspaces"`
		Panes      []struct {
			PaneID  string `json:"pane_id"`
			Project string `json:"project"`
			Slot    int    `json:"slot"`
		} `json:"panes"`
		Spaces []struct {
			WorkspaceID string `json:"workspace_id"`
			Label       string `json:"label"`
			Slot        int    `json:"slot"`
		} `json:"spaces"`
	} `json:"cases"`
}

func loadParity(t *testing.T) parity {
	t.Helper()
	data, err := os.ReadFile("testdata/parity.json")
	if err != nil {
		t.Fatal(err)
	}
	var p parity
	if err := json.Unmarshal(data, &p); err != nil {
		t.Fatal(err)
	}
	return p
}

func TestParityHashes(t *testing.T) {
	p := loadParity(t)
	for name, slot := range p.Hashes {
		if got := palette.ColourFor(name).Slot; got != slot {
			t.Errorf("ColourFor(%q) = slot %d, Python gave %d", name, got, slot)
		}
	}
}

func TestParityPlans(t *testing.T) {
	p := loadParity(t)
	for i, c := range p.Cases {
		plan := MakePlan(c.Agents, c.Workspaces)
		if len(plan.Panes) != len(c.Panes) || len(plan.Spaces) != len(c.Spaces) {
			t.Fatalf("case %d: %d panes, %d spaces; Python gave %d, %d",
				i, len(plan.Panes), len(plan.Spaces), len(c.Panes), len(c.Spaces))
		}
		for j, want := range c.Panes {
			got := plan.Panes[j]
			if got.PaneID != want.PaneID || got.Project != want.Project || got.Colour.Slot != want.Slot {
				t.Errorf("case %d pane %d: got %s %q slot %d, Python gave %s %q slot %d",
					i, j, got.PaneID, got.Project, got.Colour.Slot, want.PaneID, want.Project, want.Slot)
			}
		}
		for j, want := range c.Spaces {
			got := plan.Spaces[j]
			if got.WorkspaceID != want.WorkspaceID || got.Label != want.Label || got.Colour.Slot != want.Slot {
				t.Errorf("case %d space %d: got %s %q slot %d, Python gave %s %q slot %d",
					i, j, got.WorkspaceID, got.Label, got.Colour.Slot, want.WorkspaceID, want.Label, want.Slot)
			}
		}
	}
}

func TestProjectName(t *testing.T) {
	for in, want := range map[string]string{
		"/Users/dev/code/dashboard":   "dashboard",
		"/Users/dev/code/dashboard/":  "dashboard",
		`C:\Users\dev\code\dashboard`: "dashboard",
		`C:\Users\dev\code\dash\`:     "dash",
		`C:\`:                         "",
		"/":                           "",
		"":                            "",
	} {
		if got := ProjectName(in); got != want {
			t.Errorf("ProjectName(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestWindowsAndUnixPathsShareAColour(t *testing.T) {
	plan := MakePlan([]Agent{
		{PaneID: "w1:p1", Cwd: `C:\Users\dev\code\infra`},
		{PaneID: "w2:p1", Cwd: "/home/dev/infra"},
	}, nil)
	if plan.Panes[0].Colour != plan.Panes[1].Colour {
		t.Fatal("the same project on two platforms got two colours")
	}
}

func TestFallsBackToForegroundCwd(t *testing.T) {
	plan := MakePlan([]Agent{{PaneID: "w1:p1", ForegroundCwd: "/src/infra"}}, nil)
	if len(plan.Panes) != 1 || plan.Panes[0].Project != "infra" {
		t.Fatalf("got %+v", plan.Panes)
	}
}

func TestPanesWithoutADirectoryOrIDAreSkipped(t *testing.T) {
	plan := MakePlan([]Agent{{PaneID: "w1:p1"}, {Cwd: "/src/infra"}}, nil)
	if len(plan.Panes) != 0 {
		t.Fatalf("got %+v", plan.Panes)
	}
}

func TestTokensFillOneSlotAndClearTheRest(t *testing.T) {
	c := palette.BySlot(3)
	tokens := TokensFor("infra", c)
	if len(tokens) != len(palette.Palette)+1 || len(tokens) > 16 {
		t.Fatalf("%d tokens", len(tokens))
	}
	for _, p := range palette.Palette {
		v := tokens[palette.SlotToken(p.Slot)]
		if p.Slot == 3 {
			if v == nil || *v != "infra" {
				t.Errorf("slot 3 = %v", v)
			}
		} else if v != nil {
			t.Errorf("slot %d = %q, want cleared", p.Slot, *v)
		}
	}
	if v := tokens[palette.ColourToken]; v == nil || *v != c.Hex {
		t.Errorf("colour token = %v", v)
	}
}

func TestClearedEmptiesEverything(t *testing.T) {
	tokens := Cleared()
	if len(tokens) != len(palette.Palette)+1 {
		t.Fatalf("%d tokens", len(tokens))
	}
	for name, v := range tokens {
		if v != nil {
			t.Errorf("%s = %q", name, *v)
		}
	}
}

func TestCollidingProjectsGetDifferentColours(t *testing.T) {
	projects := map[string]bool{"project-2": true, "project-5": true, "project-7": true, "project-9": true}
	hashed := map[int]bool{}
	for p := range projects {
		hashed[palette.ColourFor(p).Slot] = true
	}
	if len(hashed) >= len(projects) {
		t.Fatal("these were chosen because they collide; they no longer do")
	}
	slots := map[int]bool{}
	for _, c := range Resolve(projects) {
		slots[c.Slot] = true
	}
	if len(slots) != len(projects) {
		t.Fatalf("%d colours for %d projects", len(slots), len(projects))
	}
}

func TestResolutionDoesNotDependOnOrder(t *testing.T) {
	a := []Agent{{PaneID: "w1:p1", Cwd: "/src/herdrcolor"}, {PaneID: "w2:p1", Cwd: "/src/api-server"}}
	b := []Agent{a[1], a[0]}
	colours := func(agents []Agent) map[string]palette.Colour {
		m := map[string]palette.Colour{}
		for _, p := range MakePlan(agents, nil).Panes {
			m[p.PaneID] = p.Colour
		}
		return m
	}
	if !reflect.DeepEqual(colours(a), colours(b)) {
		t.Fatal("agent order changed the colours")
	}
}

func TestMoreProjectsThanSlotsAllGetAColour(t *testing.T) {
	projects := map[string]bool{}
	for i := 0; i < 20; i++ {
		projects["project-"+string(rune('a'+i))] = true
	}
	if got := Resolve(projects); len(got) != 20 {
		t.Fatalf("%d of 20 assigned", len(got))
	}
}

func TestASpaceTakesItsAgentsColour(t *testing.T) {
	plan := MakePlan([]Agent{{PaneID: "w6:p1", Cwd: "/src/api-server/docs"}},
		[]Workspace{{WorkspaceID: "w6", Label: "api-server"}})
	if plan.Spaces[0].Colour != plan.Panes[0].Colour {
		t.Fatal("space and agent disagree")
	}
}

func TestAnEmptySpaceIsColouredByItsLabel(t *testing.T) {
	plan := MakePlan(nil, []Workspace{{WorkspaceID: "w9", Label: "infra"}})
	if plan.Spaces[0].Colour != palette.ColourFor("infra") {
		t.Fatal("empty space did not hash its label")
	}
}

func TestAnEmptySpaceDoesNotStealAnAgentsColour(t *testing.T) {
	plan := MakePlan([]Agent{{PaneID: "w1:p1", Cwd: "/src/project-2"}},
		[]Workspace{{WorkspaceID: "w9", Label: "project-5"}})
	if plan.Panes[0].Colour == plan.Spaces[0].Colour {
		t.Fatal("two rows, one colour")
	}
}

func TestSpacesWithoutALabelAreSkipped(t *testing.T) {
	plan := MakePlan(nil, []Workspace{{WorkspaceID: "w9"}, {WorkspaceID: "wA", Label: "infra"}})
	if len(plan.Spaces) != 1 || plan.Spaces[0].WorkspaceID != "wA" {
		t.Fatalf("got %+v", plan.Spaces)
	}
}

func TestWorkspaceOf(t *testing.T) {
	if WorkspaceOf("w6:p1") != "w6" || WorkspaceOf("wB:p12") != "wB" {
		t.Fatal("wrong prefix")
	}
}
